import { tr } from "../i18n/index.ts";
/**
 * Page uploader: pushes snapshot chunks generated by pure browser nodes to asset service
 * (M7 contract section 4.5, D7 "parent page push").
 *
 * Chunked upload interface follows header of `server/asset-service.ts` (`snap`, `px` namespaces
 * follow same rules as `media`):
 *
 *   `GET <ns>/<hash>/chunks` reconcile → missing chunks `PUT <ns>/<hash>/<n>` (each chunk carries
 *   `X-Media-Size`, `X-Media-Ext`) → `POST <ns>/<hash>/complete`
 *
 * Chunk size 8 MiB; HTML snapshots and small-size WebP are far smaller, typically one chunk.
 * Hashes already `complete` are not pushed again (content-addressed, naturally deduplicated).
 * Same hash is pushed via single-flight (concurrent second request waits for result of the first);
 * when finalize returns `400 incomplete`, re-check chunks, re-upload once and finalize again
 * (collision in M7 probe P4).
 * Writes use write ticket: `Authorization: Bearer <rw ticket>`
 * (`auth.ticket { kind: 'asset', access: 'rw' }`, renewed by host within time limit); on 401,
 * force-fetch a fresh ticket and retry this step once. Tickets never enter URLs, logs, or
 * diagnostics.
 *
 * `sha256Hex` uses WebCrypto (both browser page and Node 22 have `crypto.subtle`).
 *
 * This module belongs to the render layer (`src/online/`): does not import editor, does not read
 * compile-time constants; networking via injected `fetch`.
 */

/** Chunk size (same as `chunkSize` in `asset-service.ts`) */
export const CHUNK_SIZE = 8 * 1024 * 1024;

export type Namespace = "snap" | "px" | "media";

export interface UploaderDeps {
  /** Asset service base URL (`…/api/asset`); returns null if not connected */
  base: () => string | null;
  /** Write ticket; when `force` is true, bypasses cache and gets a fresh one. Returns null if unavailable */
  ticket: (force?: boolean) => Promise<string | null>;
  fetch?: typeof fetch;
}

export interface UploaderStats {
  /** Number of chunks and bytes actually pushed */
  pushed: number;
  pushedBytes: number;
  /** Chunks already present on asset service and skipped */
  skipped: number;
  failed: number;
  /** Number of retries with refreshed ticket after 401 */
  reauth: number;
  /** Number of times chunks were re-queried after finalize returned `incomplete` */
  recheck: number;
  lastError: string | null;
  /** Timing breakdown per request (ms, cumulative): awaiting ticket, `fetch` to response headers, reading response body; `requests` is request count */
  ms: { requests: number; ticket: number; fetch: number; body: number };
}

export interface SnapUploader {
  /** Whether this chunk is already fully received on asset service (treated as absent if query fails) */
  has(ns: Namespace, hash: string): Promise<boolean>;
  /** Pushes one chunk; returns `pushed` or `skipped` (already exists), throws on failure (`retryable` is true) */
  put(ns: Namespace, hash: string, bytes: Uint8Array, ext: string): Promise<"pushed" | "skipped">;
  stats(): UploaderStats;
}

/** SHA-256 of bytes (lowercase hex) */
export async function sha256Hex(bytes: Uint8Array | ArrayBuffer): Promise<string> {
  const buf = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const digest = await crypto.subtle.digest("SHA-256", buf as BufferSource);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

const HEX64 = /^[a-f0-9]{64}$/;
const fail = (message: string, extra: Record<string, unknown> = {}) => Object.assign(new Error(message), { retryable: true, ...extra });

export function createSnapUploader(deps: UploaderDeps): SnapUploader {
  const f = deps.fetch ?? ((...a: Parameters<typeof fetch>) => fetch(...a));
  const stats: UploaderStats = { pushed: 0, pushedBytes: 0, skipped: 0, failed: 0, reauth: 0, recheck: 0, lastError: null, ms: { requests: 0, ticket: 0, fetch: 0, body: 0 } };
  const now = () => (typeof performance !== "undefined" ? performance.now() : Date.now());

  const urlOf = (ns: Namespace, hash: string, tail: string) => {
    const base = deps.base();
    if (!base) throw fail(tr("There is no remote asset service yet"));
    return `${base.replace(/\/+$/, "")}/${ns}/${hash}${tail}`;
  };

  /** Sends once with write ticket; retries once with a fresh ticket on 401 */
  const authed = async (url: string, init: RequestInit): Promise<Response> => {
    const go = async (force: boolean) => {
      const t0 = now();
      const ticket = await deps.ticket(force);
      const t1 = now();
      const headers: Record<string, string> = { ...(init.headers as Record<string, string> | undefined) };
      if (ticket) headers.Authorization = `Bearer ${ticket}`;
      const res = await f(url, { ...init, headers });
      stats.ms.requests++;
      stats.ms.ticket += t1 - t0;
      stats.ms.fetch += now() - t1;
      return res;
    };
    const res = await go(false);
    if (res.status !== 401) return res;
    stats.reauth++;
    return go(true);
  };

  /** In-flight pushes: `<ns>/<hash>` → result */
  const inflight = new Map<string, Promise<"pushed" | "skipped">>();

  /** PUTs missing chunks */
  const putMissing = async (ns: Namespace, hash: string, bytes: Uint8Array, ext: string, received: Set<number>) => {
    const size = bytes.length;
    const count = Math.max(1, Math.ceil(size / CHUNK_SIZE));
    for (let n = 0; n < count; n++) {
      if (received.has(n)) continue;
      const body = bytes.subarray(n * CHUNK_SIZE, Math.min(size, (n + 1) * CHUNK_SIZE));
      const res = await authed(urlOf(ns, hash, `/${n}`), {
        method: "PUT",
        headers: { "Content-Type": "application/octet-stream", "X-Media-Size": String(size), "X-Media-Ext": ext },
        body: body as BodyInit,
      });
      if (!res.ok) throw fail(tr("push {0} part {1} returned {2}", ns, n, res.status), { status: res.status });
    }
  };

  /** Push a chunk: reconcile → missing chunks → finalize; if finalize returns `incomplete` (interleaved with another request), re-checks chunks, re-uploads once, and finalizes again */
  const pushOnce = async (ns: Namespace, hash: string, bytes: Uint8Array, ext: string): Promise<"pushed" | "skipped"> => {
    try {
      if (!HEX64.test(hash)) throw fail(tr("invalid hash: {0}", hash.slice(0, 16)), { retryable: false });
      if (!bytes.length) throw fail(tr("cannot push an empty chunk"), { retryable: false });
      let state = await chunksOf(ns, hash);
      if (state.complete) { stats.skipped++; return "skipped"; }
      for (let attempt = 0; ; attempt++) {
        await putMissing(ns, hash, bytes, ext, state.received);
        const done = await authed(urlOf(ns, hash, "/complete"), { method: "POST" });
        if (done.ok) break;
        const body = await done.json().catch(() => null) as { error?: string } | null;
        if (done.status === 400 && body?.error === "incomplete" && attempt === 0) {
          stats.recheck++;
          state = await chunksOf(ns, hash);
          if (state.complete) break;
          continue;
        }
        throw fail(tr("finalize {0} returned {1}{2}", ns, done.status, body?.error ? ` ${body.error}` : ""), { status: done.status });
      }
      stats.pushed++;
      stats.pushedBytes += bytes.length;
      return "pushed";
    } catch (e) {
      stats.failed++;
      stats.lastError = String((e as Error)?.message ?? e);
      throw e;
    }
  };

  const chunksOf = async (ns: Namespace, hash: string) => {
    const res = await authed(urlOf(ns, hash, "/chunks"), { method: "GET", cache: "no-store" });
    if (!res.ok) throw fail(tr("reconcile {0} returned {1}", ns, res.status), { status: res.status });
    const tb = now();
    const j = (await res.json()) as { size?: number | null; received?: number[]; complete?: boolean };
    stats.ms.body += now() - tb;
    return { complete: j?.complete === true, received: new Set(Array.isArray(j?.received) ? j.received : []) };
  };

  return {
    async has(ns, hash) {
      if (!HEX64.test(hash)) return false;
      try { return (await chunksOf(ns, hash)).complete; } catch { return false; }
    },
    put(ns, hash, bytes, ext) {
      // Single-flight by hash: if the same chunk is already being pushed, await its result (M7 probe P4: concurrent pushes of identical chunks across adjacent frames collide into `incomplete`)
      const key = `${ns}/${hash}`;
      const flying = inflight.get(key);
      if (flying) return flying.then(() => { stats.skipped++; return "skipped" as const; });
      const work = pushOnce(ns, hash, bytes, ext).finally(() => { inflight.delete(key); });
      inflight.set(key, work);
      return work;
    },
    stats: () => ({ ...stats, ms: { ...stats.ms } }),
  };
}
